<script setup lang="ts">import PmsTableControls from './PmsTableControls.vue';
import {ref,onMounted,computed} from 'vue';import {pmsApi} from './api';const tablePage=ref(1),tableSize=ref(10),search=ref('');const shown=computed(()=>rows.value.filter(row=>(row.name+' '+row.email).toLowerCase().includes(search.value.toLowerCase())));const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const rows=ref<any[]>([]),error=ref('');onMounted(async()=>{try{rows.value=(await pmsApi('team-activity','','GET',undefined,true)).data;}catch(e){error.value=(e as Error).message;}});</script><template><p v-if="error" class="notice admin-error">{{error}}</p><div class="pms-table-card"><h5 class="p-3 mb-0">Online Users</h5><div class="px-3 small text-muted">Online &nbsp; {{rows.filter(u=>u.is_online).length}}</div><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search"/><table class="pms-table"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Last Seen</th></tr></thead><tbody><tr v-for="u in paged" :key="u.id"><td>{{u.id}}</td><td>{{u.name}}</td><td>{{u.email}}</td><td>{{u.roles.map((r:any)=>r.role_name).join(', ')}}</td><td><span class="badge" :class="u.is_online?'bg-label-success':'bg-label-secondary'">{{u.is_online?'Online':'Offline'}}</span></td><td>{{u.last_seen_at?new Date(u.last_seen_at).toLocaleString():'Never'}}</td></tr><tr v-if="!rows.length"><td colspan="6">No employees in your permitted team.</td></tr></tbody></table><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div></template>